import React, { useState } from "react";
import { TEAM_FLAGS } from "../lib/bracketData";
import { predictGroup } from "../lib/apiClient";

interface GroupCardProps {
  groupName: string;
  teams: string[];
  selectedTeams: string[];
  onSelectTeam: (teamName: string) => void;
}

export const GroupCard: React.FC<GroupCardProps> = ({
  groupName,
  teams,
  selectedTeams = [],
  onSelectTeam
}) => {
  const isSelected = (team: string) => selectedTeams.includes(team);
  const reachedLimit = selectedTeams.length >= 2;

  return (
    <div className="bg-white dark:bg-slate-900 border border-gray-200 dark:border-slate-800 rounded-xl p-5 shadow-sm hover:shadow-md transition-shadow duration-200">
      <div className="flex justify-between items-center mb-4">
        <span className="text-sm font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400">
          {groupName}
        </span>
        <span className="bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 text-xs px-2.5 py-1 rounded-full font-medium">
          {selectedTeams.length} / 2 selected
        </span>
      </div>

      <div className="space-y-2">
        {teams.map(team => {
          const selected = isSelected(team);
          const disabled = !selected && reachedLimit;
          const flag = TEAM_FLAGS[team] || "🏳️";

          return (
            <button
              key={team}
              onClick={() => onSelectTeam(team)}
              disabled={disabled}
              className={`w-full flex items-center justify-between p-3 rounded-lg border text-left font-medium transition-all duration-200 hover:scale-[1.02] active:scale-95 ${
                selected
                  ? "bg-green-600 border-green-600 text-white shadow-sm"
                  : disabled
                  ? "bg-slate-50 dark:bg-slate-950 border-slate-200 dark:border-slate-850 text-slate-300 dark:text-slate-700 cursor-not-allowed hover:scale-100"
                  : "bg-slate-50 dark:bg-slate-800/50 border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800"
              }`}
            >
              <span className="flex items-center gap-3">
                <span className="text-xl" role="img" aria-label={`${team} flag`}>
                  {flag}
                </span>
                <span>{team}</span>
              </span>
              {selected && (
                <svg
                  className="w-5 h-5 text-white"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M5 13l4 4L19 7"
                  />
                </svg>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
};
